CREATE TABLE standard_commercial_policy_versions (
 version integer PRIMARY KEY CHECK(version>0), policy jsonb NOT NULL,
 created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER immutable_standard_commercial_policy BEFORE UPDATE OR DELETE ON standard_commercial_policy_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
